local function countdownTimer()
	if gameState.timeLeft > 0 and gameState.state == 1 then
		gameState.timeLeft = gameState.timeLeft - 1
	end
end
timers.countdownTimerHandle = timer.performWithDelay(400, countdownTimer,0)


local function updateFPS()
		obj.fpsTxtNum.text = gameState.fps
		gameState.fps = 0
end
timers.fpsTimer = timer.performWithDelay(1000, updateFPS,0)	

local function spawnPoints(x,y,amount)
	local points = display.newText(amount,0,0,theFontName, 16)
	gameGroup:insert( points )
	points.x = x
	points.y = y
	transition.to( points, { time=1000,y = points.y - 80} )
	
	local function destroy()
		if points.pointsDestroyTimer then 
			timer.cancel( points.pointsDestroyTimer ) 
			points.pointsDestroyTimer = nil
		end
		
		if points then 
			display.remove( points )
			points = nil
		end
	end
	points.pointsDestroyTimer = timer.performWithDelay(1100, destroy, 1)
end
local function spawnHerodie(x,y)
	local herodie = display.newImageRect( "images/herodie.png", 26, 29 )
	gameGroup:insert( herodie )
	herodie.x = x
	herodie.y = y
	audio.play( sounds.herodieSound)
	transition.to(herodie, { time=300,y=herodie.y-100})
	local function moveDown()
		transition.to(herodie, { time=500,y=herodie.y+300})	
	end
	timer.performWithDelay(310, moveDown, 1)
	
	local function reloadlevel()
		display.remove( herodie )
		herodie = nil
		gameState.state2 = 1
		gameState.state = 3
	end
	timer.performWithDelay(810, reloadlevel)
	
end
