local function spawnSpringBoard(x,y,force)
	local springBoardSheet = sprite.newSpriteSheet("images/springboardsheet.png", 64, 64)
	local springBoardSet = sprite.newSpriteSet (springBoardSheet, 1, 3)
	sprite.add (springBoardSet, "boing", 1, 6, 200, 1)
	
	
	local springBoard = sprite.newSprite (springBoardSet)
	springBoard.shape = { -16,6, 16,6, 20,20, -20,20}
	gameGroup:insert( springBoard )
	physics.addBody( springBoard , "dynamic" ,{ bounce = 0.3 , friction = 0.2 , density = 0.70, shape=springBoard.shape} ) 
	springBoard.myName = "springBoard"
	springBoard.isFixedRotation = true
	springBoard:prepare("boing")
	springBoard:play("boing")
	springBoard:pause()
	springBoard.x = x
	springBoard.y = y
	springBoard.force = force
	
	return springBoard
end
