local function spawnApplePowerup(x,y)
	local applePowerup = display.newImageRect("images/apple.png",32,32)
		applePowerup:setReferencePoint( display.TopCenterReferencePoint )
		physics.addBody( applePowerup,"static", { density=0.3, friction=0.2, bounce=0.1} )
		applePowerup.isReady = true
		applePowerup.isSensor = true
		applePowerup.x = x
		applePowerup.y = y
		applePowerup.myName = "applePowerup"
		gameGroup:insert(applePowerup)
		
	local function makeDynamic()
		applePowerup.isSensor = false
		applePowerup.isFixedRotation = true
		applePowerup.isBullet = true
		applePowerup.bodyType = "dynamic"
	end
		transition.to(applePowerup, { time=300, y=y-50,onComplete=makeDynamic} )
end
