local function spawnFireBall(x,y)
	local fireBall = display.newImageRect( "images/fireball.png", 16, 16 )
	gameGroup:insert(fireBall)
	fireBall.x = x
	fireBall.y = y
	fireBall.myName = "fireBall"
	if obj.bigHero.state == "heroFacingRight" or obj.bigHero.state == "heroRunningRight" then
		fireBall.x = fireBall.x + 16
	end
	if obj.bigHero.state == "heroFacingLeft" or obj.bigHero.state == "heroRunningLeft" then
		fireBall.x = fireBall.x - 16
	end
	physics.addBody( fireBall, "dynamic", { density=0.3, friction=0.1, bounce=0.8, radius = 8 } )					
	if obj.bigHero.state == "heroFacingRight" or obj.bigHero.state == "heroRunningRight" then
		fireBall:applyForce(  2.5, 0.85, fireBall.x, fireBall.y )
	end
	if obj.bigHero.state == "heroFacingLeft" or obj.bigHero.state == "heroRunningLeft" then
		fireBall:applyForce(  -2.5, 0.85, fireBall.x, fireBall.y )
	end
	local function removeFireBall()
		display.remove( fireBall )
		fireBall = nil
	end
	local function resetFireBall()
		gameState.throwFireBall = true
	end
	timer.performWithDelay(1000, removeFireBall)
	timer.performWithDelay(400, resetFireBall)
end	

local function spawnOrangeBadGuy(x,y)
	local orangeBadGuySheet = sprite.newSpriteSheet("images/orangebadguysheet.png", 32, 32)
	local orangeBadGuySet = sprite.newSpriteSet (orangeBadGuySheet, 1, 4)
	sprite.add (orangeBadGuySet, "orangebadguyWalking", 1, 2, 350, 0)
	sprite.add (orangeBadGuySet, "orangebadguyStomp",3, 2, 350, 1)

	local orangeBadGuy = sprite.newSprite (orangeBadGuySet)
	gameGroup:insert(orangeBadGuy)
	orangeBadGuy:prepare("orangebadguyWalking")
	orangeBadGuy.shape = { 0, -12, 12, 0, 12, 11, 0, 12, -12, 11, -12, 0}
	physics.addBody( orangeBadGuy , "dynamic" ,{ bounce = 0 , friction = 0.25 , density = 0.55, shape=orangeBadGuy.shape} )  
	orangeBadGuy.isFixedRotation = true
	orangeBadGuy.isBullet = true
	orangeBadGuy.myName = "orangebadguy"
	orangeBadGuy.myName2 = "badguy"
	orangeBadGuy.state = "walkLeft" 
						
	orangeBadGuy.vx = 0
	orangeBadGuy.vy = 0
				
	orangeBadGuy.x = x
	orangeBadGuy.y = y
	orangeBadGuy.speed = 60
	orangeBadGuy.isAlive = true
	orangeBadGuy.isStomp = false
	orangeBadGuy.isFireBall = false
	orangeBadGuy:play()
			
	function orangeBadGuy.update()
		
		if orangeBadGuy.isAlive == true then
		if (gameState.heroX > orangeBadGuy.x-800 and gameState.heroX < orangeBadGuy.x+800) then 
			orangeBadGuy.vx, orangeBadGuy.vy = orangeBadGuy:getLinearVelocity()
					
			-- walk right
			if orangeBadGuy.vx < orangeBadGuy.speed and orangeBadGuy.state == "walkRight" then
				orangeBadGuy:applyForce(  0.6, 0, orangeBadGuy.x, orangeBadGuy.y )
			end
		
			
			-- walk left
			if orangeBadGuy.vx > -orangeBadGuy.speed and orangeBadGuy.state == "walkLeft" then
				orangeBadGuy:applyForce( -0.6, 0, orangeBadGuy.x, orangeBadGuy.y )
			end
					
						
			-- jump right
			if orangeBadGuy.state == "jumpRight" then
				orangeBadGuy:applyForce( 2,-9, orangeBadGuy.x, orangeBadGuy.y )
				orangeBadGuy.state = "walkRight"
			end
					
			
			-- jump left
			if orangeBadGuy.state == "jumpLeft" then
				orangeBadGuy:applyForce( -2, -9, orangeBadGuy.x, orangeBadGuy.y )
				orangeBadGuy.state = "walkLeft"
			end
		 end
		end
		if orangeBadGuy.isAlive == false and orangeBadGuy.isStomp == true then
			orangeBadGuy:pause()
			orangeBadGuy:prepare("orangebadguyStomp")
			orangeBadGuy:play()
			orangeBadGuy.isStomp = false
		end
	 
	end
	return orangeBadGuy
	
end

local function spawnSmallDragon(x,y)
	local smallDragonSheet = sprite.newSpriteSheet("images/smalldragonsheet.png", 64, 64)
	local smallDragonSet = sprite.newSpriteSet (smallDragonSheet, 1, 8)
	sprite.add (smallDragonSet, "smallDragonWalkingLeft", 1, 4, 350, 0)
	sprite.add (smallDragonSet, "smallDragonWalkingRight",5, 4, 350, 0)

	local smallDragon = sprite.newSprite (smallDragonSet)
	gameGroup:insert(smallDragon)
	smallDragon:prepare("smallDragonWalkingLeft")
	smallDragon.shape = { 0, -24, 24, 0, 24, 22, 0, 24, -24, 22, -24, 0}
	physics.addBody( smallDragon , "dynamic" ,{ bounce = 0 , friction = 0.25 , density = 0.55, shape=smallDragon.shape} )  
	smallDragon.isFixedRotation = true
	smallDragon.isBullet = true
	smallDragon.myName = "smalldragon"
	smallDragon.myName2 = "badguy"
	smallDragon.state = "walkLeft" 
						
	smallDragon.vx = 0
	smallDragon.vy = 0
				
	smallDragon.x = x
	smallDragon.y = y
	smallDragon.speed = 60
	smallDragon.isAlive = true
	smallDragon.isStomp = false
	smallDragon.isFireBall = false
	smallDragon:play()
			
	function smallDragon.update()
		
		if smallDragon.isAlive == true then
		if (gameState.heroX > smallDragon.x-800 and gameState.heroX < smallDragon.x+800) then 
			smallDragon.vx, smallDragon.vy = smallDragon:getLinearVelocity()
					
			-- walk right
			if smallDragon.vx < smallDragon.speed and smallDragon.state == "walkRight" then
				smallDragon:applyForce(  2.0, 0, smallDragon.x, smallDragon.y )
			end
		
			
			-- walk left
			if smallDragon.vx > -smallDragon.speed and smallDragon.state == "walkLeft" then
				smallDragon:applyForce( -2.0, 0, smallDragon.x, smallDragon.y )
			end
					
						
			-- jump right
			if smallDragon.state == "jumpRight" then
				smallDragon:applyForce( 8,-30, smallDragon.x, smallDragon.y )
				smallDragon.state = "walkRight"
			end
					
			
			-- jump left
			if smallDragon.state == "jumpLeft" then
				smallDragon:applyForce( -8, -30, smallDragon.x, smallDragon.y )
				smallDragon.state = "walkLeft"
			end
		 end
		end
		if smallDragon.isAlive == false and smallDragon.isStomp == true then
			smallDragon:pause()
			smallDragon:prepare("smallDragonStomp")
			smallDragon:play()
			smallDragon.isStomp = false
		end
	 
	end
	return smallDragon
	
end
local function spawnSnake(x,y)
