obj.bigRedBadGuy1Percent = 1
local function spawnBigRedBadGuy(x,y)
	obj.bigRedBadGuy1Percent = obj.bigRedBadGuy1Percent - 0.1
	local bigRedBadGuySheet = sprite.newSpriteSheet("images/bigredsheet.png", 128, 128)
	local bigRedBadGuySet = sprite.newSpriteSet (bigRedBadGuySheet, 1, 2)
	sprite.add (bigRedBadGuySet, "bigredbadguyWalking", 1, 2, 350, 0)
	
	local bigRedBadGuy = sprite.newSprite (bigRedBadGuySet)
	gameGroup:insert(bigRedBadGuy)
	bigRedBadGuy:prepare("bigredbadguyWalking")
	bigRedBadGuy.shape = { 0, -45*obj.bigRedBadGuy1Percent, 45*obj.bigRedBadGuy1Percent, 0, 45*obj.bigRedBadGuy1Percent, 44*obj.bigRedBadGuy1Percent, 0, 45*obj.bigRedBadGuy1Percent, -45*obj.bigRedBadGuy1Percent, 44*obj.bigRedBadGuy1Percent, -45*obj.bigRedBadGuy1Percent, 0}
	physics.addBody( bigRedBadGuy , "dynamic" ,{ bounce = 0 , friction = 0.25 , density = 0.55, shape=bigRedBadGuy.shape} )  
	bigRedBadGuy.isFixedRotation = true
	bigRedBadGuy.isBullet = true
	bigRedBadGuy.myName = "bigredbadguy"
	bigRedBadGuy.myName2 = "badguy"
	bigRedBadGuy.state = "walkLeft" 
						
	bigRedBadGuy.vx = 0
	bigRedBadGuy.vy = 0
				
	bigRedBadGuy.x = x
	bigRedBadGuy.y = y
	bigRedBadGuy.speed = 60
	bigRedBadGuy.isAlive = true
	bigRedBadGuy.isStomp = false
	bigRedBadGuy.isFireBall = false
	bigRedBadGuy.xScale = obj.bigRedBadGuy1Percent
	bigRedBadGuy.yScale = obj.bigRedBadGuy1Percent
	bigRedBadGuy:play()
			
	function bigRedBadGuy.update()
		
		if bigRedBadGuy.isAlive == true then
		if (gameState.heroX > bigRedBadGuy.x-800 and gameState.heroX < bigRedBadGuy.x+800) then 
			bigRedBadGuy.vx, bigRedBadGuy.vy = bigRedBadGuy:getLinearVelocity()
					
			-- walk right
			if bigRedBadGuy.vx < bigRedBadGuy.speed and bigRedBadGuy.state == "walkRight" then
				bigRedBadGuy:applyForce(  1.3*obj.bigRedBadGuy1Percent, 0, bigRedBadGuy.x, bigRedBadGuy.y )
			end
		
			
			-- walk left
			if bigRedBadGuy.vx > -bigRedBadGuy.speed and bigRedBadGuy.state == "walkLeft" then
				bigRedBadGuy:applyForce( -1.3*obj.bigRedBadGuy1Percent, 0, bigRedBadGuy.x, bigRedBadGuy.y )
			end
					
						
			-- jump right
			if bigRedBadGuy.state == "jumpRight" then
				bigRedBadGuy:applyForce( 5*obj.bigRedBadGuy1Percent,-20*obj.bigRedBadGuy1Percent, bigRedBadGuy.x, bigRedBadGuy.y )
				bigRedBadGuy.state = "walkRight"
			end
					
			
			-- jump left
			if bigRedBadGuy.state == "jumpLeft" then
				bigRedBadGuy:applyForce( -5*obj.bigRedBadGuy1Percent, -20*obj.bigRedBadGuy1Percent, bigRedBadGuy.x, bigRedBadGuy.y )
				bigRedBadGuy.state = "walkLeft"
			end
		 end
		end
		if bigRedBadGuy.isAlive == false and bigRedBadGuy.isStomp == true then
			bigRedBadGuy:pause()
			bigRedBadGuy:prepare("bigredbadguyStomp")
			bigRedBadGuy:play()
			bigRedBadGuy.isStomp = false
		end
	 
