local function spawnCloud(color,x,y,speed,sizeX,sizeY,startX,endX)
	local cloud
	if color == "white" then
		cloud = display.newImageRect( "images/cloud.png", sizeX, sizeY )
	end
	if color == "grey" then
		cloud = display.newImageRect( "images/cloud2.png", sizeX, sizeY )
	end
	
	cloud:setReferencePoint( display.TopCenterReferencePoint )
	gameGroup:insert(cloud)
	cloud.myName = "cloud"
	physics.addBody( cloud, "static", { density=0, friction=0, bounce=0 } )
	cloud.isSensor = true 
				
	cloud.x = x
	cloud.y = y
	cloud.speed = speed
				
	function cloud.update()
		cloud.x = cloud.x - cloud.speed
		if cloud.x < startX then
			cloud.x = endX
		end
	end
	return cloud
	
end	
