local function spawnPurpleFlyBadGuy(x,y,beginX,beginY,endX,endY,mode)
	local purpleFlyBadGuySheet = sprite.newSpriteSheet("images/purplebadguysheet.png", 32, 32)
	local purpleFlyBadGuySet = sprite.newSpriteSet (purpleFlyBadGuySheet, 1, 4)
	sprite.add (purpleFlyBadGuySet, "purpleflybadguywalking", 1, 2, 350, 0)
	sprite.add (purpleFlyBadGuySet, "purpleflybadguystomp",3, 2, 350, 1)

	local purpleFlyBadGuy = sprite.newSprite (purpleFlyBadGuySet)
	gameGroup:insert(purpleFlyBadGuy)
	purpleFlyBadGuy:prepare("purpleflybadguywalking")
	purpleFlyBadGuy.shape = { 0, -12, 12, 0, 12, 11, 0, 12, -12, 11, -12, 0}
	physics.addBody( purpleFlyBadGuy , "dynamic" ,{ bounce = 0 , friction = 0.25 , density = 0.55, shape=purpleFlyBadGuy.shape} )  
	purpleFlyBadGuy.isFixedRotation = true
	purpleFlyBadGuy.isBullet = true
	purpleFlyBadGuy.myName = "purpleflybadguy"
	purpleFlyBadGuy.myName2 = "badguy"
	purpleFlyBadGuy.state = "right" 
	
	purpleFlyBadGuy.mode = mode
	
	purpleFlyBadGuy.vx = 0
	purpleFlyBadGuy.vy = 0
	
	purpleFlyBadGuy.beginX = beginX
	purpleFlyBadGuy.beginY = beginY
	purpleFlyBadGuy.endX = endX
	purpleFlyBadGuy.endY = endY
			
	purpleFlyBadGuy.x = x
	purpleFlyBadGuy.y = y
	purpleFlyBadGuy.speed = 40
	purpleFlyBadGuy.isAlive = true
	purpleFlyBadGuy.isStomp = false
	purpleFlyBadGuy.isFireBall = false
	purpleFlyBadGuy:play()
			
	function purpleFlyBadGuy.update()
		
		if purpleFlyBadGuy.isAlive == true then
			purpleFlyBadGuy.vx, purpleFlyBadGuy.vy = purpleFlyBadGuy:getLinearVelocity()
		  
			if purpleFlyBadGuy.mode == "hop" then
				if purpleFlyBadGuy.state == "right" and purpleFlyBadGuy.x < purpleFlyBadGuy.endX and purpleFlyBadGuy.vx < purpleFlyBadGuy.speed then
					purpleFlyBadGuy:applyForce( 0.1, 0, purpleFlyBadGuy.x, purpleFlyBadGuy.y )
				elseif purpleFlyBadGuy.state == "left" and purpleFlyBadGuy.x > purpleFlyBadGuy.beginX and purpleFlyBadGuy.vx > -purpleFlyBadGuy.speed then
					purpleFlyBadGuy:applyForce( -0.1, 0, purpleFlyBadGuy.x, purpleFlyBadGuy.y )
				end
		  
				if purpleFlyBadGuy.vy == 0 and purpleFlyBadGuy.vy < 5 then
					purpleFlyBadGuy:applyForce( 0, -5, purpleFlyBadGuy.x, purpleFlyBadGuy.y )
				end
				if purpleFlyBadGuy.state == "right" and purpleFlyBadGuy.x >= purpleFlyBadGuy.endX then
					purpleFlyBadGuy.state = "left"
				elseif purpleFlyBadGuy.state == "left" and purpleFlyBadGuy.x <= purpleFlyBadGuy.beginX then
					purpleFlyBadGuy.state = "right"
				end
			end
			if purpleFlyBadGuy.mode == "fly" then
				if purpleFlyBadGuy.state == "right" and purpleFlyBadGuy.x < purpleFlyBadGuy.endX and purpleFlyBadGuy.vx < purpleFlyBadGuy.speed then
					purpleFlyBadGuy:applyForce( 0.1, 0, purpleFlyBadGuy.x, purpleFlyBadGuy.y )
				elseif purpleFlyBadGuy.state == "left" and purpleFlyBadGuy.x > purpleFlyBadGuy.beginX and purpleFlyBadGuy.vx > -purpleFlyBadGuy.speed then
					purpleFlyBadGuy:applyForce( -0.1, 0, purpleFlyBadGuy.x, purpleFlyBadGuy.y )
				end
		  
				if purpleFlyBadGuy.y >= purpleFlyBadGuy.endY and purpleFlyBadGuy.vy > -1 then
					purpleFlyBadGuy:applyForce( 0, -1, purpleFlyBadGuy.x, purpleFlyBadGuy.y )
				end
				if purpleFlyBadGuy.state == "right" and purpleFlyBadGuy.x >= purpleFlyBadGuy.endX then
					purpleFlyBadGuy.state = "left"
				elseif purpleFlyBadGuy.state == "left" and purpleFlyBadGuy.x <= purpleFlyBadGuy.beginX then
					purpleFlyBadGuy.state = "right"
				end
			end
		end
		if purpleFlyBadGuy.isAlive == false and purpleFlyBadGuy.isStomp == true then
			purpleFlyBadGuy:pause()
			purpleFlyBadGuy:prepare("purpleflybadguystomp")
			purpleFlyBadGuy:play()
			purpleFlyBadGuy.isStomp = false
		end
	
	end
	return purpleFlyBadGuy
	
end	
