local function coinPattern(x,y,pattern)
	-- pattern = 1 shape
	--		*
	--	   ***
	--      *
	if pattern == 1 then
		spawnCoin(x,y)
		spawnCoin(x-40,y)
		spawnCoin(x+40,y)
		spawnCoin(x,y-40)
		spawnCoin(x,y+40)
	end
	
	-- pattern = 2 shape
	--		**
	--	    ** 
	--	    ** 
	if pattern == 2 then
		spawnCoin(x,y)
		spawnCoin(x,y+40)
		spawnCoin(x,y-40)
		spawnCoin(x+40,y)
		spawnCoin(x+40,y+40)
		spawnCoin(x+40,y-40)
	end
	
	-- pattern = 3 shape
	--		     *
	--	          *
	--	           *
	if pattern == 3 then
		spawnCoin(x,y)
		spawnCoin(x+32,y+24)
		spawnCoin(x-32,y-24)
	end
	
	-- pattern = 4 shape
	--		   *
	--	     * 
	--	   * 
	if pattern == 4 then
		spawnCoin(x,y)
		spawnCoin(x-32,y+24)
		spawnCoin(x+32,y-24)
	end
	
	-- pattern = 5 shape
	--		* * *
	--	     
	--	    
	if pattern == 5 then
		spawnCoin(x,y)
		spawnCoin(x-32,y)
		spawnCoin(x+32,y)
	end
	
	-- pattern = 6 shape
	--		* * * * * *
	--	     
	--	    
	if pattern == 6 then
		spawnCoin(x,y)
		spawnCoin(x-40,y)
		spawnCoin(x-80,y)
		spawnCoin(x+40,y)
		spawnCoin(x+80,y)
	end
	
	-- pattern = 7 shape
	--		* * *
	--		* * *
	--		* * *	
	if pattern == 7 then
		spawnCoin(x,y)
		spawnCoin(x-40,y)
		spawnCoin(x+40,y)
		
		spawnCoin(x,y+40)
		spawnCoin(x-40,y+40)
		spawnCoin(x+40,y+40)
		
		spawnCoin(x,y-40)
		spawnCoin(x-40,y-40)
		spawnCoin(x+40,y-40)
	end
end
