local function growdaddio()
	local growdaddy = display.newImageRect("images/growdad.png",28,31)
	growdaddy:setReferencePoint( display.TopCenterReferencePoint )
	gameGroup:insert( growdaddy )
	growdaddy.x = obj.tempHeroX-3
	growdaddy.y = obj.tempHeroY-32
	
	--audio.play(sounds.growdaddioSound)
	
	local function destroy()
		if growdaddioDestroyTimer then 
			timer.cancel( growdaddioDestroyTimer ) 
			growdaddioDestroyTimer = nil
		end
				
		if growdaddy then 
			display.remove( growdaddy )
			growdaddy = nil
		end
	end
	local growdaddioDestroyTimer = timer.performWithDelay(1050, destroy, 1)
	transition.to( growdaddy, { time=1000,yScale = 1.5} )
end
local function shrinkdaddio(x,y)
	local shrinkdaddy = display.newImageRect("images/growdad.png",28,31)
	shrinkdaddy:setReferencePoint( display.TopCenterReferencePoint )
	gameGroup:insert( shrinkdaddy )
	shrinkdaddy.x = x-3
	shrinkdaddy.y = y-32
	shrinkdaddy.yScale = 1.5
	
	
	local function destroy()
		if shrinkdaddioDestroyTimer then 
			timer.cancel( shrinkdaddioDestroyTimer ) 
			shrinkdaddioDestroyTimer = nil
		end
				
		if shrinkdaddy then 
			display.remove( shrinkdaddy )
			shrinkdaddy = nil
		end
	end
	local shrinkdaddioDestroyTimer = timer.performWithDelay(550, destroy, 1)
	transition.to( shrinkdaddy, { time=500,yScale = 1} )
end
local function spawnThrowBrick(x,y)
	local throwBrick = display.newImageRect( "images/crackedblock.png", 32, 32 )
	throwBrick.x = x
	throwBrick.y = y
	throwBrick.myName = "throwbrick"
	throwBrick.myName2 = "ground"
	throwBrick.throwBrickisPickup = false
	throwBrick.throwBrickisCarry = false
	throwBrick.isAlive = true
	gameGroup:insert(throwBrick) 
	throwBrick.shape = { -14,-14, 14,-14, 14,14, -14,14}
	physics.addBody( throwBrick, { density=0.2, friction=4, bounce=0,shape=throwBrick.shape } )
	function throwBrick.update()
		if throwBrick.isAlive == true then
			if (gameState.heroX > throwBrick.x-400 and gameState.heroX < throwBrick.x+400) then
				if gameState.throwBrickisPickup == true and throwBrick.throwBrickisPickup == true then
					audio.play( sounds.pickupblocksoundSound)
					gameState.throwBrickisPickup = false
					gameState.throwBrickisCarry = true
					throwBrick.throwBrickisCarry = true
					throwBrick.bodyType = "static"
					--throwBrick.isSensor = true
				end
								
				if gameState.heroSize == "big" and gameState.throwBrickisCarry == true and throwBrick.throwBrickisCarry == true then
					if obj.bigHero.state == "heroFacingRight" or obj.bigHero.state == "heroRunningRight" then
						throwBrick.x = obj.bigHero.x + 34
						throwBrick.y = obj.bigHero.y - 5
					end
					if obj.bigHero.state == "heroFacingLeft" or obj.bigHero.state == "heroRunningLeft" then
						throwBrick.x = obj.bigHero.x - 34						
						throwBrick.y = obj.bigHero.y - 5
					end			
					if throwBrick.throwBrickisCarry == true and gameState.throwTheBrick == true and (obj.bigHero.state == "heroFacingRight" or obj.bigHero.state == "heroRunningRight") then
						audio.play( sounds.throwblocksoundSound)
						throwBrick.x = obj.bigHero.x + 40
						throwBrick.y = obj.bigHero.y - 5
						throwBrick.bodyType = "dynamic"
						throwBrick.isSensor = false
						gameState.throwBrickisPickup = false
						gameState.throwBrickisCarry = false
						gameState.throwTheBrick = false
						throwBrick.throwBrickisPickup = false
						throwBrick.throwBrickisCarry = false
						throwBrick.throwTheBrick = false
						throwBrick:applyForce(5, -2, throwBrick.x-1, throwBrick.y+1 )
						if gameState.firepower == false then
							if obj.bigHero.state == "heroFacingRight" then
