								obj.bigHero:prepare("redheroFacingLeft")
								obj.bigHero:play()
							end
							if obj.bigHero.state == "heroRunningRight" then
								obj.bigHero:pause()
								obj.bigHero:prepare("redheroRunningRight")
								obj.bigHero:play()
							end
							if obj.bigHero.state == "heroRunningLeft" then
								obj.bigHero:pause()
								obj.bigHero:prepare("redheroRunningLeft")
								obj.bigHero:play()
							end
							if obj.bigHero.state == "heroJumpRight" then
								obj.bigHero:pause()
								obj.bigHero:prepare("redheroJumpRight")
								obj.bigHero:play()
							end
							if obj.bigHero.state == "heroJumpLeft" then
								obj.bigHero:pause()
								obj.bigHero:prepare("redheroJumpLeft")
								obj.bigHero:play()
							end
						end
					end
				end
				if gameState.heroSize == "small" and gameState.throwBrickisCarry == true and throwBrick.throwBrickisCarry == true then
					if obj.smallHero.state == "heroFacingRight" or obj.smallHero.state == "heroRunningRight" then
						throwBrick.x = obj.smallHero.x + 32
						throwBrick.y = obj.smallHero.y - 15
					end
					if obj.smallHero.state == "heroFacingLeft" or obj.smallHero.state == "heroRunningLeft" then
						throwBrick.x = obj.smallHero.x - 32
						throwBrick.y = obj.smallHero.y - 15
					end			
					if throwBrick.throwBrickisCarry == true and gameState.throwTheBrick == true and (obj.smallHero.state == "heroFacingRight" or obj.smallHero.state == "heroRunningRight") then
						audio.play( sounds.throwblocksoundSound)
						throwBrick.x = obj.smallHero.x + 40
						throwBrick.y = obj.smallHero.y - 12
						throwBrick.bodyType = "dynamic"
						throwBrick.isSensor = false
						gameState.throwBrickisPickup = false
						gameState.throwBrickisCarry = false
						gameState.throwTheBrick = false
						throwBrick.throwBrickisPickup = false
						throwBrick.throwBrickisCarry = false
						throwBrick.throwTheBrick = false
						throwBrick:applyForce( 5, -2, throwBrick.x-1, throwBrick.y+1 )
						if obj.smallHero.state == "heroFacingRight" then
							obj.smallHero:pause()
							obj.smallHero:prepare("heroFacingRight")
							obj.smallHero:play()
						end
						if obj.smallHero.state == "heroFacingLeft" then
							obj.smallHero:pause()
							obj.smallHero:prepare("heroFacingLeft")
							obj.smallHero:play()
						end
						if obj.smallHero.state == "heroRunningRight" then
							obj.smallHero:pause()
							obj.smallHero:prepare("heroRunningRight")
							obj.smallHero:play()
						end
						if obj.smallHero.state == "heroRunningLeft" then
							obj.smallHero:pause()
							obj.smallHero:prepare("heroRunningLeft")
							obj.smallHero:play()
						end
						if obj.smallHero.state == "heroJumpRight" then
							obj.smallHero:pause()
							obj.smallHero:prepare("heroJumpRight")
							obj.smallHero:play()
						end
						if obj.smallHero.state == "heroJumpLeft" then
							obj.smallHero:pause()
							obj.smallHero:prepare("heroJumpLeft")
							obj.smallHero:play()
						end
					end
					if throwBrick.throwBrickisCarry == true and gameState.throwTheBrick == true and (obj.smallHero.state == "heroFacingLeft" or obj.smallHero.state == "heroRunningLeft") then
						audio.play( sounds.throwblocksoundSound)
						throwBrick.x = obj.smallHero.x - 40
						throwBrick.y = obj.smallHero.y - 12
						throwBrick.bodyType = "dynamic"
						throwBrick.isSensor = false
						gameState.throwBrickisPickup = false
						gameState.throwBrickisCarry = false
						gameState.throwTheBrick = false
						throwBrick.throwBrickisPickup = false
						throwBrick.throwBrickisCarry = false
						throwBrick.throwTheBrick = false
						throwBrick:applyForce( -5, -2, throwBrick.x-1, throwBrick.y+1 )
						if obj.smallHero.state == "heroFacingRight" then
							obj.smallHero:pause()
							obj.smallHero:prepare("heroFacingRight")
							obj.smallHero:play()
						end
						if obj.smallHero.state == "heroFacingLeft" then
							obj.smallHero:pause()
							obj.smallHero:prepare("heroFacingLeft")
							obj.smallHero:play()
						end
						if obj.smallHero.state == "heroRunningRight" then
							obj.smallHero:pause()
							obj.smallHero:prepare("heroRunningRight")
							obj.smallHero:play()
						end
						if obj.smallHero.state == "heroRunningLeft" then
							obj.smallHero:pause()
							obj.smallHero:prepare("heroRunningLeft")
							obj.smallHero:play()
						end
						if obj.smallHero.state == "heroJumpRight" then
							obj.smallHero:pause()
							obj.smallHero:prepare("heroJumpRight")
							obj.smallHero:play()
						end
						if obj.smallHero.state == "heroJumpLeft" then
							obj.smallHero:pause()
							obj.smallHero:prepare("heroJumpLeft")
							obj.smallHero:play()
						end
					end
				end
			end
		end
		
	end
	return throwBrick
end
local function spawnDoor(x,y,myName)
	local doorSheet = sprite.newSpriteSheet("images/bluedoorsheet.png", 128, 128)
	local doorSet = sprite.newSpriteSet (doorSheet, 1, 10)
	sprite.add (doorSet, "closedoor", 1, 10, 350,1)
	
					
 	local door = sprite.newSprite(doorSet)			
	door:prepare("closedoor")
	
	door.shape = { -20, -35, 20, -35, 20,35 -20,35}
	
	gameGroup:insert( door )
			
	physics.addBody( door , "static" ,{ bounce = 0 , friction = 0 , density = 0, shape=door.shape} )  
	door.isSensor = true
	door.myName = myName
	
	door.state = "dooropen" 
		
	door.x = x
	door.y = y
	return door
end
local function spawnPlatform(x,y,width)
		local platform = display.newImageRect("images/platform.png",width,12)
		platform:setReferencePoint( display.TopCenterReferencePoint )
		physics.addBody( platform,"static", { density=0, friction=0.2, bounce=0} )
		platform.x = x
		platform.y = y
		platform.myName = "platform"
		platform.myName2 = "ground"
		gameGroup:insert(platform)
		platform:toFront()
		
end
local function spawnMoveUpPlatform(x,y,distanceY,width)
		local platform = display.newImageRect("images/platform.png",width,12)
		platform:setReferencePoint( display.TopCenterReferencePoint )
		physics.addBody( platform,"kinematic", { density=0, friction=0.2, bounce=0} )
		platform.x = x
		platform.y = y
		platform.startX = x
		platform.startY = y
		platform.endX = x
		platform.endY = y - distanceY
		platform.moveUpFlag = true
		platform.myName = "platform"
		platform.myName2 = "ground"
		gameGroup:insert(platform)
		platform:toFront()
		function platform.update()
			if platform.y >= platform.endY and platform.moveUpFlag == true then
				platform.y = platform.y - 1
			elseif platform.y <= platform.startY and platform.moveUpFlag == false then
				platform.y = platform.y + 1
			end
			if platform.y > platform.startY and platform.moveUpFlag == false then
				platform.moveUpFlag = true
			elseif platform.y < platform.endY and platform.moveUpFlag == true then
				platform.moveUpFlag = false
			end
		end
	return platform
end
local function spawnMoveDownPlatform(x,y,distanceY,width)
		local platform = display.newImageRect("images/platform.png",width,12)
		platform:setReferencePoint( display.TopCenterReferencePoint )
		physics.addBody( platform,"kinematic", { density=0, friction=0.2, bounce=0} )
		platform.x = x
		platform.y = y
		platform.startX = x
		platform.startY = y
		platform.endX = x
		platform.endY = y + distanceY
		platform.moveDownFlag = true
		platform.myName = "platform"
		platform.myName2 = "ground"
		gameGroup:insert(platform)
		platform:toFront()
		function platform.update()
			if platform.y <= platform.endY and platform.moveDownFlag == true then
				platform.y = platform.y + 1
			elseif platform.y >= platform.startY and platform.moveDownFlag == false then
				platform.y = platform.y - 1
			end
			if platform.y < platform.startY and platform.moveDownFlag == false then
				platform.moveDownFlag = true
			elseif platform.y > platform.endY and platform.moveDownFlag == true then
				platform.moveDownFlag = false
			end
		end
	return platform
end
local function spawnBridge(x,y,numBoards)
		
		local pole1 = display.newImageRect( "images/invisableground.png", 24, 24 )
		pole1:setReferencePoint( display.TopCenterReferencePoint )
		--local pole1 = display.newImage( "bamboo.png" )
		gameGroup:insert(pole1) 
		pole1.x = x 
		pole1.y = y
		pole1.alpha = 0
		physics.addBody( pole1, "static", { friction=0.5 } )
		
		
		local pole2 = display.newImageRect( "images/invisableground.png", 24, 24 )
		pole2:setReferencePoint( display.TopCenterReferencePoint )
		gameGroup:insert(pole2)
		pole2.x = ((25*numBoards)+pole1.x)-2
		pole2.y = pole1.y
		pole2.alpha = 0
		physics.addBody( pole2, "static", { friction=0.5 } )


		local board = {}
		local joint = {}

		
		
		
		for j = 1,numBoards do
			board[j] = display.newImage( "images/board.png" )
			gameGroup:insert(board[j]) 
			board[j].myName2 = "ground"
			board[j].x = (pole1.x-22) + (j*26)
			board[j].y = (pole1.y-5)
			physics.addBody( board[j], { density=0.8, friction=0.3, bounce=0.3 } )
	
			-- damping the board motion increases the "tension" in the bridge
			board[j].angularDamping = 5000
			board[j].linearDamping = 0.7

			-- create joints between boards
			if (j > 1) then
				prevLink = board[j-1] -- each board is joined with the one before it
			else
				prevLink = pole1 -- first board is joined to left pole
			end
			joint[j] = physics.newJoint( "pivot", prevLink, board[j], (pole1.x-36)+(j*26), (pole1.y-5) )
		end

		-- join final board to right pole
		joint[#joint + 1] = physics.newJoint( "pivot", board[numBoards], pole2, (pole1.x-36)+((numBoards+1)*26), (pole1.y-5) )

end
