local function spawnFish(x,y,endY,delay)
local fishSheet = sprite.newSpriteSheet("images/fishsheet.png", 64, 64)
	local fishSet = sprite.newSpriteSet (fishSheet, 1, 8)
	sprite.add (fishSet, "fishflyup", 1, 4, 350, 0)
	sprite.add (fishSet, "fishflydown",5, 4, 350, 0)

	local fish = sprite.newSprite (fishSet)
	gameGroup:insert(fish)
	fish:prepare("fishflyup")
	fish.shape = { 0, -12, 12, 0, 12, 11, 0, 12, -12, 11, -12, 0}
	physics.addBody( fish , "dynamic" ,{ bounce = 0 , friction = 0.25 , density = 0.55, shape=fish.shape} )  
	fish.isFixedRotation = true
	fish.isBullet = true
	fish.myName = "fish"
	fish.myName2 = "fish"
	fish.state = "up" 
	
	fish.mode = "up"
	
	fish.vx = 0
	fish.vy = 0
	
	fish.beginY = y
	fish.endY = endY

	fish.time = 0
	fish.delay = delay

	
	fish.x = x
	fish.y = y
	fish.speed = -300
	fish.isAlive = true
	fish.isStomp = false
	fish.isFireBall = false
	fish:play()
			
	function fish.update()
		
		if fish.isAlive == true then
			fish.vx, fish.vy = fish:getLinearVelocity()
			fish.time = fish.time + 1
			if fish.mode == "up" then
				if fish.state == "up" and fish.time > fish.delay and fish.vy > fish.speed then
					fish:applyForce( 0, -1, fish.x, fish.y )
				end
				if fish.y < fish.endY then
					fish.mode = "down"
					fish:pause()
					fish:prepare("fishflydown")
					fish:play()
				end
		  	end
			if fish.mode == "down" then
				if fish.state == "down" then
					-- gravity does the work
				end
				if fish.y > fish.beginY then
					fish.time = 0
					fish.mode = "up"
					fish:pause()
					fish:prepare("fishflyup")
					fish:play()
				end
		  	end
		end
	
	end
	return fish
	
end
local function spawnPlant(x,y)
local plantSheet = sprite.newSpriteSheet("images/plantsheet.png", 64, 64)
	local plantSet = sprite.newSpriteSet (plantSheet, 1, 2)
	sprite.add (plantSet, "plantchomp", 1, 2, 350, 0)
	

	local plant = sprite.newSprite (plantSet)
	gameGroup:insert(plant)
	plant:prepare("plantchomp")
	plant.shape = { -12, -22, 12,-22, 12,30, -12,30}
	physics.addBody( plant , "dynamic" ,{ bounce = 0 , friction = 100.25 , density = 100.55, shape=plant.shape} )  
	plant.isFixedRotation = true
	plant.isBullet = true
	plant.myName = "plant"
	plant.myName2 = "badguy"
			
	plant.x = x
	plant.y = y
	
	plant.isAlive = true
	plant.isStomp = false
	plant.isFireBall = false
	plant:play()
	
end
local function spawnGreenBug(x,y)
	local greenBugSheet = sprite.newSpriteSheet("images/bugsheet.png", 32, 32)
	local greenBugSet = sprite.newSpriteSet (greenBugSheet, 1, 4)
	sprite.add (greenBugSet, "greenBugWalkingLeft", 1, 2, 350, 0)
	sprite.add (greenBugSet, "greenBugWalkingRight",3, 2, 350, 0)

	local greenBug = sprite.newSprite (greenBugSet)
	gameGroup:insert(greenBug)
	greenBug:prepare("greenBugWalkingLeft")
	greenBug.shape = { 0, -12, 12, 0, 12, 11, 0, 12, -12, 11, -12, 0}
	physics.addBody( greenBug , "dynamic" ,{ bounce = 0 , friction = 0.25 , density = 0.55, shape=greenBug.shape} )  
	greenBug.isFixedRotation = true
	greenBug.isBullet = true
	greenBug.myName = "greenBug"
	greenBug.myName2 = "badguy"
	greenBug.state = "walkLeft" 
						
	greenBug.vx = 0
	greenBug.vy = 0
				
	greenBug.x = x
	greenBug.y = y
	greenBug.speed = 80
	greenBug.isAlive = true
	greenBug.isStomp = false
	greenBug.isFireBall = false
	greenBug:play()
			
	function greenBug.update()
		
		if greenBug.isAlive == true then
		if (gameState.heroX > greenBug.x-800 and gameState.heroX < greenBug.x+800) then 
			greenBug.vx, greenBug.vy = greenBug:getLinearVelocity()
					
			-- walk right
			if greenBug.vx < greenBug.speed and greenBug.state == "walkRight" then
				greenBug:applyForce(  0.6, 0, greenBug.x, greenBug.y )
			end
		
			
			-- walk left
			if greenBug.vx > -greenBug.speed and greenBug.state == "walkLeft" then
				greenBug:applyForce( -0.6, 0, greenBug.x, greenBug.y )
			end
					
						
			-- jump right
			if greenBug.state == "jumpRight" then
				greenBug:applyForce( 2,-9, greenBug.x, greenBug.y )
				greenBug.state = "walkRight"
			end
					
			
			-- jump left
			if greenBug.state == "jumpLeft" then
				greenBug:applyForce( -2, -9, greenBug.x, greenBug.y )
				greenBug.state = "walkLeft"
			end
		 end
		end
		
	end
	return greenBug
	
end

