local function unLoadLevel()
	gameState.state = 0
	
	-- pause physics engine
	physics.pause()
	
	-- cancel timers
	timer.cancel( timers.countdownTimerHandle )
	timer.cancel( timers.fpsTimer )	
	
	
	
	-- 2 second delay before removing display objects to make sure all transitions are completed
	local function removeGroups()
		-- pause/stop all audio channels
		audio.pause()
		audio.stop()
		
		if gameState.state2 == 1 then
			storyboard.gotoScene( "loadlevel" )
		end
		if gameState.state2 == 2 and lastLevelCompleted == false then
			storyboard.gotoScene( "levelcomplete" )
		end
		if (gameState.state2 == 3) or (gameState.state2 == 2 and lastLevelCompleted == true) then
			storyboard.gotoScene( "selectworld" )
		end
	end
	timer.performWithDelay(2000, removeGroups)
end	

