-- touch event for control buttons
local function touchListener(event)   
	if gameState.state == 1 then
		-- left button
		if event.x >= 0 and event.x <= 126 and event.y >= 0 and event.y <= 480 then
		if event.phase == "began" then
			if gameState.heroSize == "small" then
				if gameState.throwBrickisCarry == false then
					obj.smallHero.state = "heroRunningLeft"
					obj.smallHero:pause()
					obj.smallHero:prepare("heroRunningLeft")
					obj.smallHero:play()
