					audio.resume(sounds.backgroundMusicChannel)
				end
				
				transition.to(background, { time=500, alpha=1,} )
				transition.to(gameGroup, { time=500, alpha=1,} )
				transition.to(rainGroup, { time=500, alpha=1,} )
				transition.to(snowGroup, { time=500, alpha=1,} )
				transition.to(hudGroup, { time=500, alpha=1} )
				transition.to(obj.pause1, { time=500, y=-1, x=-1} )
				transition.to(obj.pause2, { time=500, y=-1, x=801} )
				transition.to(obj.pause3, { time=500, y=481, x=-1} )
				transition.to(obj.pause4, { time=500, y=481, x=801} )
				if gameState.heroSize == "small" then
					obj.smallHero.alpha = 0
					spawnHerodie(obj.smallHero.x,obj.smallHero.y)
				end
				if gameState.heroSize == "big" then
					obj.bigHero.alpha = 0
					spawnHerodie(obj.bigHero.x,obj.bigHero.y)
				end
			end
		end
		if event.x >= 300 and event.x <= 500 and event.y >= 300 and event.y <= 340 then
			if event.phase == "began" then
			
			end
			if event.phase == "ended" or event.phase == "canceled" then
				audio.play( sounds.coinSound)
				obj.loadingLabel = display.newText("Loading menu...",0,0,theFontName, 32)
				obj.loadingLabel.x = 400
				obj.loadingLabel.y = 370
				pauseGroup:insert(  obj.loadingLabel )
				gameState.state = 0
				gameState.state2 = 3
				unLoadLevel()
				
			end
		end
		
	end
end 		
