			end
		end
		
	end
	end
end
Runtime:addEventListener( "collision", onCollision )

-- remove object after certain amount of force like block
local function onPostCollision( event )
	if gameState.state == 1 then
	 local function removeObject1AfterDelay()
        if event.object1.myName == "coinblock" then
			spawnBreakableBrick(event.object1.x,event.object1.y)
		end
		if event.object1.myName == "applepowerupblock" then
			spawnApplePowerup(event.object1.x,event.object1.y)
			spawnBreakableBrick(event.object1.x,event.object1.y)
		end
		if event.object1.myName == "fireflowerpowerupblock" then
			spawnFireFlowerPowerup(event.object1.x,event.object1.y)
			spawnBreakableBrick(event.object1.x,event.object1.y)
		end
		display.remove(event.object1)
		event.object1 = nil
    end
    local function removeObject2AfterDelay()
        if event.object2.myName == "coinblock" then
			spawnBreakableBrick(event.object2.x,event.object2.y)
		end 
		if event.object2.myName == "applepowerupblock" then
			spawnApplePowerup(event.object2.x,event.object2.y)
			spawnBreakableBrick(event.object2.x,event.object2.y)
		end
		if event.object2.myName == "fireflowerpowerupblock" then
			spawnFireFlowerPowerup(event.object2.x,event.object2.y)
			spawnBreakableBrick(event.object2.x,event.object2.y)
		end
		display.remove(event.object2)
		event.object2 = nil
    end
	
