	sounds.backgroundNatureChannel = audio.play( sounds.backgroundNature, { channel=3, loops=-1} )  
	audio.setVolume( 0.25, { channel=3 } )
end
if obj.isDay == true and audioSettings:retrieve( "musicOn" ) == "false" then
	sounds.backgroundNature = audio.loadStream("trackday.ogg")
	sounds.backgroundNatureChannel = audio.play( sounds.backgroundNature, { channel=3, loops=-1} )  
	audio.setVolume( 0.45, { channel=3 } )
end
if obj.isNight == true and audioSettings:retrieve( "musicOn" ) == "false" then
